    "qaContract": {
      "mathematics": [
        "all starting, equivalent and result fractions agree across prompt, visual, answer and working",
        "core unlike-addition items have different denominators and neither divides the other",
        "each common denominator is divisible by both source denominators",
        "equivalent rewrites preserve exact value",
        "converted numerators add to the authored result numerator",
        "larger valid common denominators and exact equivalent results are accepted",
        "no item silently requires simplification or mixed-number conversion"
      ],
      "leakage": [
        "scored pre-submit speech never states a required common denominator, equivalent numerator or result",
        "hints begin closed and do not contain the final answer",
        "previous solved work clears before each independent, final and recovery item",
        "accessible pre-submit descriptions do not infer the requested answer",
        "final and recovery working cannot render until answerLocked is true"
      ],
      "runtimeCopy": [
        "Ryan TTS and captions resolve only from FRA19_RUNTIME_COPY",
        "audio and captions use the same utterance id and exact text",
        "timed cue anchor text exists inside its utterance",
        "no author-only field leaks into speech or captions",
        "correct and incorrect utterances are distinct and mutually exclusive",
        "no orphan cue remains after a speech change",
        "no added spoken line semantically repeats another line without a new function"
      ],
      "routes": [
        "clean G1/G2 evidence skips F1 but never F2",
        "supported independent success creates a fresh no-hint confirmation obligation",
        "repeated central errors select the matching repair and fresh recheck",
        "the explained repair item never counts as recovery evidence",
        "M1-M5 complete before final-score routing interrupts the sequence",
        "4-5, 3 and 0-2 final routes behave exactly as authored",
        "recovery item selection excludes seen ids and requires the authored all-correct threshold"
      ],
      "visual": [
        "equal-length source rails have identical endpoints",
        "equal partitions are geometrically equal",
        "third-sized and quarter-sized pieces are visibly different widths",
        "subdivision never changes the selected endpoint",
        "context screens use light rails, reflective tape or cable as authored rather than unrelated generic imagery",
        "desktop, approximately 390 px mobile and reduced-motion states receive manual visual inspection"
      ]
    },
