  "misconceptions": [
    {
      "code": "DIRECT_ADD",
      "learnerVisibleMeaning": "The response adds the visible numerators and denominators before the part sizes match.",
      "observableResponses": [
        "a/b + c/d is submitted as (a+c)/(b+d)",
        "the learner explicitly states that both top and bottom numbers should be added",
        "a completed method line keeps unlike source fractions and immediately combines their visible numbers"
      ],
      "immediateUiFeedback": "The pieces are different sizes. Make one shared part size before adding.",
      "classificationRule": "An explicit direct-add rule is sufficient. Otherwise require the same pattern twice or a fresh discriminating item before activating R-DIRECT.",
      "repairId": "R-DIRECT"
    },
    {
      "code": "ONE_SIDE_SCALE",
      "learnerVisibleMeaning": "A denominator changes but its numerator does not use the same factor.",
      "observableResponses": [
        "3/8 is rewritten as 3/24",
        "an equivalent-fraction field changes only the denominator",
        "a method option preserves the original numerator while changing the part size"
      ],
      "immediateUiFeedback": "The denominator changed, so the numerator must use the same factor.",
      "classificationRule": "One fully visible completed rewrite is strong evidence. For a partial or ambiguous response, give a neutral factor prompt before classification.",
      "repairId": "R-SCALE"
    },
    {
      "code": "WRONG_FACTOR",
      "learnerVisibleMeaning": "Both numbers move, but the numerator and denominator do not use the same scale factor.",
      "observableResponses": [
        "3/8 is rewritten as 6/24",
        "the denominator factor is correct but the numerator uses another factor",
        "the selected completed line contains an exact common denominator but a value-changing numerator"
      ],
      "immediateUiFeedback": "Read the denominator factor first, then use that exact factor on top.",
      "classificationRule": "Classify from a clearly inconsistent completed rewrite or a repeat after an exact-factor cue.",
      "repairId": "R-SCALE"
    },
    {
      "code": "INVALID_COMMON_DENOMINATOR",
      "learnerVisibleMeaning": "The chosen denominator is not divisible by both starting denominators.",
      "observableResponses": [
        "a candidate fails an exact divisibility check for either source denominator",
        "the learner explicitly says that a denominator only needs to work for one fraction",
        "the learner repeats an invalid candidate after being asked to check both denominators"
      ],
      "immediateUiFeedback": "Check that both starting denominators divide into it exactly.",
      "classificationRule": "One invalid selection receives a concise retry. Activate R-COMMON after a second invalid selection or an explicit invalid rule.",
      "repairId": "R-COMMON"
    },
    {
      "code": "ADD_COMMON_DENOMINATORS",
      "learnerVisibleMeaning": "The learner creates matching denominators and then adds or changes them again.",
      "observableResponses": [
        "9/24 + 10/24 is submitted as 19/48",
        "the learner explicitly says that both top and bottom numbers must be added after conversion",
        "a result uses the correct converted numerator sum with the wrong added denominator"
      ],
      "immediateUiFeedback": "The piece size is already fixed. Add the numerators and keep the common denominator.",
      "classificationRule": "Activate R-KEEP after a repeat, a failed fixed-denominator cue or an explicit add-both rule.",
      "repairId": "R-KEEP"
    },
    {
      "code": "ARITHMETIC",
      "learnerVisibleMeaning": "The fraction method is structurally correct, but one multiplication or numerator addition fact is wrong.",
      "observableResponses": [
        "the common denominator and both factors are correct except one nearby whole-number product",
        "the two equivalent fractions are correct but the numerator sum is one arithmetic fact away"
      ],
      "immediateUiFeedback": "Your method is sound. Recheck the highlighted number fact.",
      "classificationRule": "Never infer a fraction misconception from one arithmetic slip. Keep secure structural evidence and use the smaller arithmetic-slip route."
    },
    {
      "code": "MALFORMED",
      "learnerVisibleMeaning": "The submitted response is blank, partial, unparsable or has a zero denominator.",
      "observableResponses": [
        "blank input",
        "non-integer field",
        "partial fraction",
        "zero denominator"
      ],
      "immediateUiFeedback": "Enter a complete fraction with a non-zero denominator.",
      "classificationRule": "Use neutral field validation. Do not assign a misconception or reveal the answer."
    },
    {
      "code": "UNKNOWN",
      "learnerVisibleMeaning": "The visible response does not support a confident mathematical interpretation.",
      "observableResponses": [
        "a wrong but non-diagnostic fraction",
        "a response that could arise from several different intermediate errors",
        "an unexplained choice without a traceable distractor family"
      ],
      "immediateUiFeedback": "Show the step you are using.",
      "classificationRule": "Use a fresh discriminating item rather than pretending to know the learner's thinking."
    }
  ],
